import numpy as np

def rotate2d(p, th):
    x, y = p
    c, s = np.cos(th), np.sin(th)
    return np.array([x * c - y * s, x * s + y * c])

p = np.array([1.0, 0.0])
for deg in (0, 90, 180, 270):
    r = rotate2d(p, np.radians(deg))
    print(deg, "deg ->", np.round(r, 4))

def f_score(g, h):
    return g + h

def is_admissible(h_values, true_values, tol=1e-9):
    for node, h in h_values.items():
        if h > true_values.get(node, float("inf")) + tol:
            return False
    return True

