import numpy as np

N = np.array([-1.0, 0.0, 0.0])
FORCES = [
    np.array([-12.000, 0.000, 0.000]),
    np.array([-6.000, 2.500, 9.000]),
]

def normal_part(f, n):
    return np.dot(f, n) * n

def tangent_part(f, n):
    return f - normal_part(f, n)

for f in FORCES:
    fn = normal_part(f, N)
    ft = tangent_part(f, N)
    print("force", np.round(f, 2),
          "squeeze N", round(float(np.linalg.norm(fn)), 3),
          "slide N", round(float(np.linalg.norm(ft)), 3),
          "rebuilt", bool(np.allclose(fn + ft, f)))

NS_PER_SECOND = 1000000000
NS_PER_MS = 1000000

def period_ns(hz):
    return NS_PER_SECOND // hz

def duty_ns(pulse_ms):
    return int(pulse_ms * NS_PER_MS)

for hz in (50, 400):
    print(hz, "Hz -> period", period_ns(hz), "ns")
for pulse_ms in (1.0, 1.5, 2.0):
    print(pulse_ms, "ms -> duty", duty_ns(pulse_ms), "ns")

