LAMBDA = 100.0
X0 = 1.0
DURATION = 1.0

def decay(dt):
    x = X0
    for _ in range(int(round(DURATION / dt))):
        x = x + (-LAMBDA * x) * dt
    return x

for dt in (0.005, 0.019, 0.021, 0.03):
    print(dt, "%.4e" % abs(decay(dt)))

